mapper.select:
SELECT 
FROM device_log


        AND device_log.device_id = #{queryForm.deviceId}


        AND INSTR(device_log.device_name, #{queryForm.deviceName})


        AND device_log.type = #{queryForm.type}


        AND device_log.create_time >= #{queryForm.createTimeBegin}


        AND device_log.create_time <= #{queryForm.createTimeEnd}



    ORDER BY device_log.id DESC
